def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def evaluate(x):
        return func(x)

    pop = rng.uniform(lb, ub, (100, dim))
    best_solution = None
    best_value = 1e9

    for _ in range(budget):
        scores = np.array([evaluate(clip(x)) for x in pop])
        idxs = np.argsort(scores)[:10]
        parents = pop[idxs]

        mean = np.mean(parents, axis=0)
        cov = np.cov(parents.T)

        new_pop = []
        for i in range(100):
            parent_idx = rng.choice(len(parents))
            child = parents[parent_idx] + rng.normal(size=dim) * 1.5
            mutation = rng.normal(size=dim, loc=0, scale=np.sqrt(np.diag(cov)))
            child += mutation

            new_pop.append(clip(child))

        pop = np.array(new_pop)

        if evaluate(clip(pop[np.argmin(scores)])) < best_value:
            best_value = evaluate(clip(pop[np.argmin(scores)]))
            best_solution = clip(pop[np.argmin(scores)])

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def objective(x):
        return func(x)

    pop_size = 50
    max_iter = int(budget / pop_size)
    mutation_rate = 0.5
    temp = 1.0

    x_best = rng.uniform(lb, ub, size=dim)
    f_best = objective(clip(x_best))

    for _ in range(max_iter):
        for _ in range(pop_size):
            mutant = clip(x_best + mutation_rate * (rng.uniform(-1, 1, size=dim) - 0.5))
            if rng.rand() < 0.01:
                # Simulated annealing: occasionally accept worse solutions
                temp *= 0.99
                f_mutant = objective(clip(mutant))
                if f_mutant < f_best * (1 + 1e-6):
                    x_best, f_best = mutant, f_mutant
            else:
                # Differential evolution crossover
                trial = clip(0.5 * x_best + 0.5 * mutant)
                f_trial = objective(trial)
                if f_trial < f_best:
                    x_best, f_best = trial, f_trial

    return x_best

